SET LOCAL search_path = "stats_transfer_holdings", pg_catalog;
CREATE SCHEMA IF NOT EXISTS "stats_transfer_holdings";
CREATE TABLE "stats_transfer_holdings".tokens(token text PRIMARY KEY, decimals smallint NOT NULL CHECK(decimals BETWEEN 0 AND 255), creation_height numeric(78,0) NOT NULL CHECK(creation_height>=0), coverage text NOT NULL CHECK(coverage IN ('complete','incomplete','quarantined')), supply numeric(78,0) NOT NULL DEFAULT 0 CHECK(supply>=0 AND supply<=115792089237316195423570985008687907853269984665640564039457584007913129639935), expected_initial_supply numeric(78,0) CHECK(expected_initial_supply>=0 AND expected_initial_supply<=115792089237316195423570985008687907853269984665640564039457584007913129639935), creation_transaction_hash text, revision bigint NOT NULL DEFAULT 0, first_event jsonb, last_event jsonb);
CREATE TABLE "stats_transfer_holdings".transfers(identity text PRIMARY KEY,token text NOT NULL REFERENCES "stats_transfer_holdings".tokens(token),digest text NOT NULL,event jsonb NOT NULL,revision bigint NOT NULL);
CREATE TABLE "stats_transfer_holdings".balances(token text NOT NULL REFERENCES "stats_transfer_holdings".tokens(token),address text NOT NULL,balance numeric(78,0) NOT NULL CHECK(balance>0 AND balance<=115792089237316195423570985008687907853269984665640564039457584007913129639935),category text NOT NULL DEFAULT 'unknown' CHECK(category IN ('unknown','external_wallet','pool_reserve','burn','treasury','router')),classification_version bigint NOT NULL DEFAULT 0,PRIMARY KEY(token,address));
CREATE INDEX ON "stats_transfer_holdings".balances(token,balance DESC,address ASC);
CREATE INDEX ON "stats_transfer_holdings".balances(token,category,balance DESC,address ASC);
CREATE TABLE "stats_transfer_holdings".incidents(identity text PRIMARY KEY,token text NOT NULL,event jsonb NOT NULL,reason text NOT NULL);
CREATE TABLE "stats_transfer_holdings".legacy_rows(pool text NOT NULL,address text NOT NULL,raw text NOT NULL,normalized_address text,numeric_balance numeric(78,0),reason text NOT NULL,PRIMARY KEY(pool,address));
CREATE TABLE "stats_transfer_holdings".classifications(token text NOT NULL REFERENCES "stats_transfer_holdings".tokens,address text NOT NULL,category text NOT NULL CHECK(category IN ('unknown','external_wallet','pool_reserve','burn','treasury','router')),version bigint NOT NULL CHECK(version>0),evidence text NOT NULL,PRIMARY KEY(token,address));
CREATE TABLE "stats_transfer_holdings".aggregates(token text NOT NULL REFERENCES "stats_transfer_holdings".tokens,category text NOT NULL,band smallint NOT NULL CHECK(band BETWEEN 0 AND 9),population bigint NOT NULL CHECK(population>=0),raw numeric(78,0) NOT NULL CHECK(raw>=0),PRIMARY KEY(token,category,band));
CREATE TABLE "stats_transfer_holdings".provenance(identity text PRIMARY KEY REFERENCES "stats_transfer_holdings".transfers,payload jsonb NOT NULL);
CREATE TABLE "stats_transfer_holdings".snapshots(snapshot_id uuid PRIMARY KEY,token text NOT NULL,pool text NOT NULL,metadata jsonb NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX ON "stats_transfer_holdings".snapshots(expires_at);
CREATE TABLE "stats_transfer_holdings".snapshot_balances(snapshot_id uuid NOT NULL REFERENCES "stats_transfer_holdings".snapshots ON DELETE CASCADE,address text NOT NULL,balance numeric(78,0) NOT NULL CHECK(balance>0),category text NOT NULL,PRIMARY KEY(snapshot_id,address));
CREATE INDEX ON "stats_transfer_holdings".snapshot_balances(snapshot_id,balance DESC,address ASC);
CREATE TABLE "stats_transfer_holdings".checkpoints(token text NOT NULL,projection_version text NOT NULL,height numeric(78,0) NOT NULL,revision bigint NOT NULL,coverage_start numeric(78,0) NOT NULL,digest text NOT NULL,position jsonb NOT NULL,PRIMARY KEY(token,projection_version,height));
REVOKE ALL ON "stats_transfer_holdings"."tokens" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."transfers" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."balances" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."incidents" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."legacy_rows" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."classifications" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."aggregates" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."provenance" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."snapshots" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."snapshot_balances" FROM PUBLIC;
REVOKE ALL ON "stats_transfer_holdings"."checkpoints" FROM PUBLIC;
